#include "resident/kernel/fixed_service_history.hpp"
namespace hanmo::resident {using namespace repair_detail;
namespace {
void cause(const MomentOwnerSource&s){if(s.source_schema<1||!valid_source_ref(s.source_ref))fail("RepairActualChangeSourceRequired");}
void settle(CommonStore&c,ItemInstancesState&i,ActionElapsedStore&e,const RepairWriteContext&x,const RepairJob&j,const WorldMoment&at){const auto*entry=find_fixed_elapsed(e,j.action_id);if(!entry)fail("RepairElapsedHistoryRequired",j.id);if(compare(entry->last_settled_at,at)>0)fail("RepairChangeBeforeSettledTime",j.id);if(std::holds_alternative<ElapsedRunning>(entry->timing)&&compare(entry->last_settled_at,at)<0)take(provide_repair_service_interval_in_candidate(c,i,e,x,j.id,{entry->last_settled_at,at}));}
FixedServiceTransition transition(const RepairReadContext&x,const RepairJob&j,const StableId&id,const WorldMoment&at){const auto history=transitions(x,j);const auto*entry=find_fixed_elapsed(x.elapsed,j.action_id);if(!entry||history.empty())fail("RepairElapsedHistoryRequired",j.id);FixedServiceTransition result;result.transition_id=id;result.action_ref=j.action_id;result.transition_ordinal=add(history.back().transition_ordinal,1);result.previous_transition_ref=history.back().transition_id;result.occurred_at=at;result.credited_at=entry->credited_units;result.execution_source_ref=repair_job_source(j.id);result.execution_source_schema=1;result.previous_input_basis_refs=history.back().input_basis_refs;return result;}
void end_action(CommonStore&c,const RepairJob&j){const auto*a=c.action(j.action_id);const auto*actor=c.actor(j.terms.worker_id);if(!a||a->actor_id!=j.terms.worker_id||a->participants!=std::vector<StableId>{j.terms.worker_id}||!actor||actor->action_id!=j.action_id)fail("RepairActualWorkerBindingRequired",j.id);ActorMutation free;free.actor_id=j.terms.worker_id;free.action_id=StableId{};take(c.apply_actor(free));ActionMutation end;end.kind=ActionMutation::Kind::erase;end.action.id=j.action_id;take(c.apply_action(end));}
}
Status validate_original_repair_control(const RepairReadContext&x,const RepairJob&j,const RepairControlSource&c){try{
 if(!c.facility_until)return x.original.validate_repair_control(j,c);
 if(c.kind!=RepairControlKind::suspended||c.job_id!=j.id||!x.occupancy||compare(c.occurred_at,now(x))>0)fail("RepairUntilControlIdentityMismatch",c.id);const auto cut=header(x.common,repair_control_source(c.id));take(validate_craft_facility_until_cause(*x.occupancy,j.terms.workstation,*c.facility_until,c.actual_cause,c.occurred_at));
 const auto history=transitions(x,j);const FixedServiceTransition*previous=nullptr;for(const auto&t:history){SourceRef actual;if(const auto*a=std::get_if<FixedOwnerAdopted>(&t.cause))actual=a->owner_source_ref;else if(const auto*a=std::get_if<FixedOwnerStateChanged>(&t.cause))actual=a->owner_source_ref;else continue;if(header(x.common,actual)>=cut)continue;if(previous&&t.transition_ordinal<=previous->transition_ordinal)fail("RepairUntilInputPrefixOrderMismatch",c.id);previous=&t;}
 if(!previous||previous->input_basis_refs.empty()||previous->input_basis_refs.size()!=c.adopted_inputs.size())fail("RepairUntilRetainedInputsRequired",c.id);for(std::size_t n=0;n<c.adopted_inputs.size();++n)if(!same_fixed_input_ref(previous->input_basis_refs[n],c.adopted_inputs[n]))fail("RepairUntilRetainedInputMismatch",c.id);
 return common_success();
}catch(Failure&e){return {false,{},std::move(e.error)};}}
namespace {
Outcome<StableId> apply_control(CommonStore&c,ItemInstancesState&i,ActionElapsedStore&e,const RepairWriteContext&x,const StableId&id,RepairControlKind kind,const MomentOwnerSource&actual,const FacilityClaimUntilRequest*until){try{
 writable(c,i,e,x);cause(actual);auto*j=i.repair_jobs.jobs.find(id);if(!j)fail("RepairJobRequired",id);const auto at=now(x.read);std::optional<CraftFacilityClaimUntil>actual_until;if(until){if(kind!=RepairControlKind::suspended||compare(until->occurred_at,at)||compare(until->due_claim.until,at)||!x.read.occupancy)fail("RepairUntilPauseIdentityMismatch",id);actual_until=CraftFacilityClaimUntil{until->due_claim.claim_id,until->admission_receipt_ref};take(validate_craft_facility_until_cause(*x.read.occupancy,j->terms.workstation,*actual_until,actual,at));}
 auto same_until=[](const auto&a,const auto&b){return a.has_value()==b.has_value()&&(!a||(a->claim_id==b->claim_id&&a->admission_receipt_ref.slot_ref==b->admission_receipt_ref.slot_ref&&a->admission_receipt_ref.claim_set_revision==b->admission_receipt_ref.claim_set_revision));};
 for(const auto&row:i.repair_jobs.controls.rows())if(row.second.job_id==id&&row.second.actual_cause.source_schema==actual.source_schema&&same_source_ref(row.second.actual_cause.source_ref,actual.source_ref)&&same_until(row.second.facility_until,actual_until)&&(!actual_until||!compare(row.second.occurred_at,at))){if(row.second.kind!=kind)fail("ConflictingRepairControlReplay",id);take(validate_original_repair_control(x.read,*j,row.second));return {true,row.first,{}};}
 take(read_original_repair_job(x.read,id));if((kind==RepairControlKind::resumed&&j->phase!=RepairJobPhase::suspended)||(kind!=RepairControlKind::resumed&&j->phase!=RepairJobPhase::working))fail("RepairControlPhaseMismatch",id);settle(c,i,e,x,*j,at);
 const auto source=take(c.next_id("repair_control"));RepairControlSource changed{source,id,kind,at,actual,{},actual_until};take(c.append_fact({source,"repair_control","crafting"}));if(!i.repair_jobs.controls.insert(source,std::move(changed)))fail("DuplicateRepairControl",source);auto*stored=i.repair_jobs.controls.find(source);
 auto claims=take(x.effects.apply_repair_control_claims_in_candidate(*j,*stored));for(const auto&claim:claims){if(claim.empty()||std::find(j->claim_refs.begin(),j->claim_refs.end(),claim)!=j->claim_refs.end())fail("DuplicateRepairAdoptedClaim",id);j->claim_refs.push_back(claim);}if(actual_until){const auto prior=transitions(x.read,*j);if(prior.empty())fail("RepairUntilPriorInputsRequired",id);stored->adopted_inputs=prior.back().input_basis_refs;}else stored->adopted_inputs=take(x.read.original.read_repair_control_inputs(*j,kind,actual,at));if(stored->adopted_inputs.empty())fail("RepairActualInputSourceRequired",id);take(validate_original_repair_control(x.read,*j,*stored));
 auto change=transition(x.read,*j,source,at);change.kind=kind==RepairControlKind::suspended?FixedTransitionKind::suspended:kind==RepairControlKind::resumed?FixedTransitionKind::resumed:FixedTransitionKind::input_rebound;change.cause=FixedOwnerStateChanged{repair_control_source(source),1,"original_repair_service_inputs"};change.input_basis_refs=stored->adopted_inputs;j->control_refs.push_back(source);j->phase=kind==RepairControlKind::suspended?RepairJobPhase::suspended:RepairJobPhase::working;
 NativeRepairActionTimeRead original(x.read);auto prepared=take(prepare_fixed_service_change(e,j->action_id,change,kind==RepairControlKind::suspended?std::optional<StableId>{actual.source_ref.id}:std::nullopt,repair_action_time_registration(),x.read.scale,original,x.read.arithmetic_budget));take(apply_fixed_service_change_in_candidate(e,std::move(prepared),repair_action_time_registration(),x.read.scale,original,x.read.arithmetic_budget));ActionMutation projection;projection.action.id=j->action_id;projection.remaining_ticks=take(fixed_elapsed_remaining_ticks(*find_fixed_elapsed(e,j->action_id),x.read.scale,x.read.arithmetic_budget));take(c.apply_action(projection));take(validate_craft_facility_occupancies(*x.read.occupancy));return {true,source,{}};
}catch(Failure&error){return {false,{},std::move(error.error)};}}
}
Outcome<StableId> apply_repair_control_in_candidate(CommonStore&c,ItemInstancesState&i,ActionElapsedStore&e,const RepairWriteContext&x,const StableId&id,RepairControlKind kind,const MomentOwnerSource&cause){return apply_control(c,i,e,x,id,kind,cause,nullptr);}
Outcome<StableId> apply_repair_facility_until_pause_in_candidate(CommonStore&c,ItemInstancesState&i,ActionElapsedStore&e,const RepairWriteContext&x,const StableId&id,const FacilityClaimUntilRequest&until){if(!x.read.occupancy)return {false,{},common_failure("RepairUntilOccupancyProviderRequired",id,ErrorKind::unsupported_capability).error};const auto receipt=read_facility_claim_receipt(x.read.occupancy->claims,until.admission_receipt_ref);if(!receipt.ok)return {false,{},receipt.error};return apply_control(c,i,e,x,id,RepairControlKind::suspended,{receipt.value.source_result_ref,receipt.value.source_schema},&until);}
Outcome<StableId> interrupt_repair_in_candidate(CommonStore&c,ItemInstancesState&i,ActionElapsedStore&e,const RepairWriteContext&x,const StableId&id,const MomentOwnerSource&actual){try{
 writable(c,i,e,x);cause(actual);auto*j=i.repair_jobs.jobs.find(id);if(!j)fail("RepairJobRequired",id);if(j->interrupted_ref){const auto*old=i.repair_jobs.interruptions.find(*j->interrupted_ref);if(!old||old->actual_cause.source_schema!=actual.source_schema||!same_source_ref(old->actual_cause.source_ref,actual.source_ref))fail("ConflictingRepairInterruptionReplay",id);take(x.read.original.validate_repair_interruption(*j,*old));return {true,old->id,{}};}
 take(read_original_repair_job(x.read,id));if(j->phase!=RepairJobPhase::working&&j->phase!=RepairJobPhase::suspended)fail("RepairAlreadyTerminal",id);const auto at=now(x.read);settle(c,i,e,x,*j,at);const auto source=take(c.next_id("repair_interrupted"));RepairInterruptedSource ended{source,id,at,actual};take(c.append_fact({source,"repair_interrupted","crafting"}));if(!i.repair_jobs.interruptions.insert(source,std::move(ended)))fail("DuplicateRepairInterruption",source);take(x.read.original.validate_repair_interruption(*j,*i.repair_jobs.interruptions.find(source)));
 auto change=transition(x.read,*j,source,at);change.kind=FixedTransitionKind::terminal;change.cause=FixedOwnerTerminated{repair_interrupted_source(source),1};change.terminal_disposition=FixedTerminalDisposition::interrupted;j->interrupted_ref=source;j->phase=RepairJobPhase::interrupted;take(x.effects.apply_repair_terminal_facility_disposition_in_candidate(*j,repair_interrupted_source(source),at));NativeRepairActionTimeRead original(x.read);auto prepared=take(prepare_fixed_service_change(e,j->action_id,change,{},repair_action_time_registration(),x.read.scale,original,x.read.arithmetic_budget));take(apply_fixed_service_change_in_candidate(e,std::move(prepared),repair_action_time_registration(),x.read.scale,original,x.read.arithmetic_budget));end_action(c,*j);take(validate_craft_facility_occupancies(*x.read.occupancy));
 take(consume_original_repair_termination_finance_in_candidate(c,i,*x.original_economy,*x.read.commercial_sources,j->terms.fee_terms_ref,{repair_interrupted_source(source),1}));
 // Professional interruption does not authorize a player cancellation, a
 // refund, or release of the customer's held item/materials. Original S7/S5
 // fee/custody sources settle those remaining responsibilities.
 return {true,source,{}};
}catch(Failure&error){return {false,{},std::move(error.error)};}}
Status adopt_repair_return_in_candidate(CommonStore&c,ItemInstancesState&i,ActionElapsedStore&e,const RepairWriteContext&x,const StableId&id,const SourceRef&actual){try{
 writable(c,i,e,x);header(c,actual);auto*j=i.repair_jobs.jobs.find(id);if(!j||j->phase==RepairJobPhase::working||j->phase==RepairJobPhase::suspended||j->phase==RepairJobPhase::reserved)fail("RepairOriginalTerminalRequired",id);if(j->returned_ref&&*j->returned_ref!=actual.id)fail("ConflictingRepairReturnReplay",id);if(j->facility_occupancy_event_refs.empty())fail("RepairActualPlacementRequired",id);const auto*placement=x.facility_occupancy_owner->facility_occupancy_events.find(j->facility_occupancy_event_refs.back());if(!placement||placement->occupancy_kind!=CraftFacilityOccupancyKind::cleared)fail("RepairActualClearanceBeforeReturnRequired",id,ErrorKind::unsupported_capability);j->returned_ref=actual.id;take(x.read.original.validate_repair_return(*j));return common_success();
}catch(Failure&error){return {false,{},std::move(error.error)};}}
}
